  ('g2-s5-area_perimeter-difficult-0001', 2, 5, 'area_perimeter', 'difficult', '{"total_area": 72, "length": 6, "part_width": 7}'::jsonb, 'A rectangle has area 72 sq cm and length 6 cm. It is divided into two parts along its length; one part has width 7 cm. What is that part''s area?', '["30", "42", "6", "84"]'::jsonb, '42', '["gave the other part''s area instead", "multiplied the part width by the whole width instead of the length", "gave the length instead of an area"]'::jsonb, 'The whole width is 72/6 = 12 cm. This part''s width is 7 cm, so its area = 7 x 6 = 42 sq cm.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
